import React, { useState, useEffect } from 'react';
import { adminService } from '../../services/adminService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage, formatDateTime } from '../../utils/helpers';
import { OPERATING_REGIONS } from '../../utils/constants';

const VendorManagement = () => {
  const [vendors, setVendors] = useState([]);
  const [filteredVendors, setFilteredVendors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [filters, setFilters] = useState({
    region: '',
    search: ''
  });

  useEffect(() => {
    loadVendors();
  }, []);

  useEffect(() => {
    applyFilters();
  }, [vendors, filters]);

  const loadVendors = async () => {
    try {
      setLoading(true);
      setError('');
      const response = await adminService.getAllVendors();
      setVendors(response.data);
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  const applyFilters = () => {
    let filtered = [...vendors];

    // Filter by region
    if (filters.region) {
      filtered = filtered.filter(vendor => 
        vendor.operatingRegion && vendor.operatingRegion.toLowerCase() === filters.region.toLowerCase()
      );
    }

    // Filter by search term
    if (filters.search) {
      const searchTerm = filters.search.toLowerCase();
      filtered = filtered.filter(vendor =>
        (vendor.name && vendor.name.toLowerCase().includes(searchTerm)) ||
        (vendor.user?.username && vendor.user.username.toLowerCase().includes(searchTerm)) ||
        (vendor.user?.email && vendor.user.email.toLowerCase().includes(searchTerm)) ||
        (vendor.cuisineSpecialties && vendor.cuisineSpecialties.toLowerCase().includes(searchTerm))
      );
    }

    setFilteredVendors(filtered);
  };

  const handleFilterChange = (filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  };

  const clearFilters = () => {
    setFilters({
      region: '',
      search: ''
    });
  };

  if (loading) {
    return <LoadingSpinner message="Loading vendors..." />;
  }

  return (
    <div className="vendor-management-page">
      <div className="container">
        <div className="page-header">
          <h1>Vendor Management</h1>
          <p>Manage all registered food truck vendors</p>
        </div>

        {error ? (
          <div className="error-container">
            <div className="error-message">
              <p>{error}</p>
              <button onClick={loadVendors} className="btn btn-primary">
                Try Again
              </button>
            </div>
          </div>
        ) : (
          <>
            {/* Filters */}
            <div className="filters-section">
              <div className="filters-row">
                <div className="filter-group">
                  <label htmlFor="search">Search</label>
                  <input
                    type="text"
                    id="search"
                    placeholder="Search by name, username, email, or cuisine..."
                    value={filters.search}
                    onChange={(e) => handleFilterChange('search', e.target.value)}
                  />
                </div>

                <div className="filter-group">
                  <label htmlFor="region">Region</label>
                  <select
                    id="region"
                    value={filters.region}
                    onChange={(e) => handleFilterChange('region', e.target.value)}
                  >
                    <option value="">All Regions</option>
                    {OPERATING_REGIONS.map(region => (
                      <option key={region} value={region}>{region}</option>
                    ))}
                  </select>
                </div>

                <div className="filter-actions">
                  <button onClick={clearFilters} className="btn btn-outline">
                    Clear Filters
                  </button>
                </div>
              </div>
            </div>

            {/* Results Summary */}
            <div className="results-summary">
              <p>
                Showing {filteredVendors.length} of {vendors.length} vendors
              </p>
            </div>

            {/* Vendors Table */}
            {filteredVendors.length > 0 ? (
              <div className="vendors-table-container">
                <table className="vendors-table">
                  <thead>
                    <tr>
                      <th>Business Name</th>
                      <th>Owner</th>
                      <th>Contact</th>
                      <th>Cuisine</th>
                      <th>Region</th>
                      <th>Status</th>
                      <th>Joined</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredVendors.map((vendor) => (
                      <tr key={vendor.id}>
                        <td>
                          <div className="vendor-name">
                            <strong>{vendor.name}</strong>
                            {vendor.licenseNumber && (
                              <span className="license-badge">Licensed</span>
                            )}
                          </div>
                        </td>
                        <td>
                          <div className="owner-info">
                            <div>{vendor.user?.username || 'N/A'}</div>
                            <small>{vendor.user?.email || 'N/A'}</small>
                          </div>
                        </td>
                        <td>
                          <div className="contact-info">
                            {vendor.phoneNumber && (
                              <div>{vendor.phoneNumber}</div>
                            )}
                            {vendor.businessAddress && (
                              <small>{vendor.businessAddress}</small>
                            )}
                          </div>
                        </td>
                        <td>{vendor.cuisineSpecialties || 'N/A'}</td>
                        <td>
                          <span className="region-badge">
                            {vendor.operatingRegion}
                          </span>
                        </td>
                        <td>
                          <span className={`status-badge ${vendor.profileComplete ? 'complete' : 'incomplete'}`}>
                            {vendor.profileComplete ? 'Complete' : 'Incomplete'}
                          </span>
                        </td>
                        <td>{formatDateTime(vendor.createdAt)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="no-results">
                <h3>No vendors found</h3>
                <p>Try adjusting your filters or search terms.</p>
                <button onClick={clearFilters} className="btn btn-primary">
                  Clear All Filters
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default VendorManagement;
